 const [user,setUser]=useState<User|null>(null),[token,setToken]=useState(()=>sessionStorage.getItem("rf-session")||""),[apiStatus,setApiStatus]=useState("checking"),[mobile,setMobile]=useState(false),[section,setSection]=useState<Section>("Overview"), [orgDashboardOpen,setOrgDashboardOpen]=useState(false),[identity,setIdentity]=useState(""),[password,setPassword]=useState(""),[showPassword,setShowPassword]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState("");
 const [inviteTarget,setInviteTarget]=useState<{id:string;name:string}|null>(null),[inviteEmail,setInviteEmail]=useState(""),[inviteBusy,setInviteBusy]=useState(false),[inviteUrl,setInviteUrl]=useState(""),[inviteCopied,setInviteCopied]=useState(false);
 const [orgSettings,setOrgSettings]=useState({name:"",logoUrl:"",primaryColor:"#6568e9",secondaryColor:"#898cff",welcomeMessage:"",footerText:"",contactEmail:"",contactPhone:"",website:""});
 const [platformOverview,setPlatformOverview]=useState<any>(null),[organizations,setOrganizations]=useState<any[]>([]),[orgApplications,setOrgApplications]=useState<any[]>([]),[orgWorkspace,setOrgWorkspace]=useState<any>(null),[auditActivities,setAuditActivities]=useState<any[]>([]),[auditTotal,setAuditTotal]=useState(0),[auditOrgFilter,setAuditOrgFilter]=useState("");
 const [accessData,setAccessData]=useState<any>({roles:[],members:[],permissions:[]}),[roleDraft,setRoleDraft]=useState({id:"",name:"",description:"",permissions:[] as string[]}),[roleMember,setRoleMember]=useState(""),[selectedRoleIds,setSelectedRoleIds]=useState<string[]>([]),[accessBusy,setAccessBusy]=useState(false);
 const [users,setUsers]=useState<User[]>([]),[staffSearch,setStaffSearch]=useState(""),[staffStatus,setStaffStatus]=useState("all"),[newUser,setNewUser]=useState({username:"",email:"",displayName:"",password:"",role:"Interviewer" as Role}),[creating,setCreating]=useState(false);
 const [events,setEvents]=useState<Event[]>([]),[activeEvent,setActiveEvent]=useState(""),[eventForm,setEventForm]=useState({name:"SKN IEEE Recruitment 2026",slug:"skn-ieee-recruitment-2026",startsAt:"",endsAt:""}),[savingEvent,setSavingEvent]=useState(false);
 const [team,setTeam]=useState<User[]>([]),[teamUser,setTeamUser]=useState(""),[teamRole,setTeamRole]=useState<Role>("Interviewer");
 const [panels,setPanels]=useState<Panel[]>([]),[interviewers,setInterviewers]=useState<User[]>([]),[selectedInterviewer,setSelectedInterviewer]=useState(""),[selectedPanel,setSelectedPanel]=useState("");
 const [candidates,setCandidates]=useState<any[]>([]),[candidateSearch,setCandidateSearch]=useState("");
 const [selection,setSelection]=useState<any[]>([]),[analytics,setAnalytics]=useState<any>(null),[dashboardAnalytics,setDashboardAnalytics]=useState<any>(null),[eventTimeline,setEventTimeline]=useState<any[]>([]),[upcomingInterviews,setUpcomingInterviews]=useState<any[]>([]),[interviewTiming,setInterviewTiming]=useState<any>({active:[],recent:[],stats:{}}),[interviewPerformance,setInterviewPerformance]=useState<any>({panels:[],interviewers:[],alerts:[],summary:{}}),[interviewTimeLimit,setInterviewTimeLimit]=useState(15),[savingTimeLimit,setSavingTimeLimit]=useState(false),[queue,setQueue]=useState<any[]>([]),[queuePanel,setQueuePanel]=useState(""),[activeInterview,setActiveInterview]=useState<any>(null),[scores,setScores]=useState({technical:7,communication:7,problemSolving:7,domainKnowledge:7,feedback:""}),[progress,setProgress]=useState<any>(null),[panelCalls,setPanelCalls]=useState<any[]>([]);
 const checkHealth=useCallback(async()=>{try{const h=await api("/api/health");setApiStatus(h.database==="connected"?"online":"offline")}catch{setApiStatus("offline")}},[]);
 const loadPlatformOverview=useCallback(async(t:string)=>{const d=await api("/api/platform/overview",t);setPlatformOverview(d)},[]);
 const loadAudit=useCallback(async(t:string,org="")=>{const d=await api("/api/platform/audit?limit=150"+(org?"&organizationId="+encodeURIComponent(org):""),t);setAuditActivities(d.activities);setAuditTotal(d.total)},[]);
 const loadOrganizations=useCallback(async(t:string)=>{const d=await api("/api/platform/organizations",t);setOrganizations(d.organizations)},[]);
 const loadOrgApplications=useCallback(async(t:string)=>{const d=await api("/api/platform/organization-applications?status=pending",t);setOrgApplications(d.applications)},[]);
 const loadOrgWorkspace=useCallback(async(t:string)=>{const d=await api("/api/organization/workspace",t);setOrgWorkspace(d.organization);const b=d.organization.branding||{};setOrgSettings({name:d.organization.name||"",logoUrl:d.organization.logo_url||"",primaryColor:d.organization.primary_color||"#6568e9",secondaryColor:d.organization.secondary_color||"#898cff",welcomeMessage:b.welcomeMessage||"",footerText:b.footerText||"",contactEmail:b.contactEmail||"",contactPhone:b.contactPhone||"",website:b.website||""})},[]);
 async function reviewOrgApplication(id:string,decision:"approve"|"reject"){if(!window.confirm(decision==="approve"?"Approve this organisation application? This creates its organisation record; workspace access is not enabled yet.":"Reject this organisation application?"))return;try{await api("/api/platform/organization-applications/"+id,token,{method:"PATCH",body:JSON.stringify({decision})});await Promise.all([loadOrgApplications(token),loadOrganizations(token),loadPlatformOverview(token)]);setNotice(decision==="approve"?"Application approved. Organisation record created; workspace onboarding remains to be completed.":"Application rejected.")}catch(e){setError((e as Error).message)}}
 function inviteOrganizationAdmin(id:string,name:string){setError("");setInviteEmail("");setInviteUrl("");setInviteCopied(false);setInviteTarget({id,name})}
 async function submitOrganizationInvite(e:FormEvent){e.preventDefault();if(!inviteTarget)return;setInviteBusy(true);setError("");try{const d=await api("/api/platform/organizations/"+inviteTarget.id+"/invitations",token,{method:"POST",body:JSON.stringify({email:inviteEmail})});setInviteUrl(d.invitationUrl);setInviteCopied(false);setNotice("Administrator invitation created for "+inviteEmail+". Copy the link below and share it securely.")}catch(e){setError((e as Error).message)}finally{setInviteBusy(false)}}
 async function copyOrganizationInvite(){try{await navigator.clipboard.writeText(inviteUrl);setInviteCopied(true)}catch{const el=document.getElementById("organization-invite-url") as HTMLInputElement|null;if(el){el.focus();el.select();setInviteCopied(false)}}}
 async function uploadOrganizationLogo(e:ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;setError("");if(!["image/png","image/jpeg","image/webp"].includes(file.type)){setError("Choose a PNG, JPG or WEBP image.");e.target.value="";return}if(file.size>10*1024*1024){setError("Logo image must be 10 MB or smaller.");e.target.value="";return}try{const imageData=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error("Could not read image file."));reader.readAsDataURL(file)});const d=await api("/api/organization/logo",token,{method:"POST",body:JSON.stringify({imageData})});setOrgSettings(old=>({...old,logoUrl:d.logoUrl}));setOrgWorkspace((old:any)=>old?({...old,logo_url:d.logoUrl}):old);setNotice("Organisation logo uploaded. Save branding & settings to keep all changes.");}catch(err){setError((err as Error).message)}finally{e.target.value=""}}
 async function saveOrganizationSettings(e:FormEvent){e.preventDefault();try{const d=await api("/api/organization/settings",token,{method:"PATCH",body:JSON.stringify(orgSettings)});setOrgWorkspace(d.organization);setNotice("Organisation branding and settings saved successfully.");}catch(e){setError((e as Error).message)}}
 async function setOrganizationStatus(id:string,status:string){try{await api("/api/platform/organizations/"+id+"/status",token,{method:"PATCH",body:JSON.stringify({status})});await Promise.all([loadOrganizations(token),loadPlatformOverview(token)]);setNotice("Organisation status updated.")}catch(e){setError((e as Error).message)}}
 const loadUsers=useCallback(async(t:string)=>{const path=user?.role==="Organization Admin"?"/api/organization/staff":"/api/auth/users";const d=await api(path,t);const rows=Array.isArray(d.users)?d.users:Array.isArray(d.staff)?d.staff:[];setUsers(rows);setInterviewers(rows.filter((u:User)=>u.role==="Interviewer"&&u.active))},[user?.role]);
 const loadEvents=useCallback(async(t:string)=>{const d=await api("/api/events",t);setEvents(d.events);setActiveEvent((old:string)=>old&&d.events.some((e:Event)=>e.id===old)?old:(d.events[0]?.id||""))},[]);
 const loadOrganizationEvents=useCallback(async(t:string)=>{const d=await api("/api/organization/events",t);const rows:Event[]=d.events||[];setEvents(rows);setActiveEvent((old:string)=>old&&rows.some(e=>e.id===old)?old:(rows[0]?.id||""))},[]);
 const loadTeam=useCallback(async(t:string,e:string)=>{if(!e){setTeam([]);setInterviewers([]);return}const d=await api("/api/events/"+e+"/team",t);setTeam(d.team);setInterviewers(d.team.filter((u:User)=>u.role==="Interviewer"))},[]);
